//! The hidden `mock-server` subcommand: a stdio MCP server that answers `tools/call`
//! straight out of a resolved `MockSet`, materialized to disk by `trg ai skills eval run`.
//!
//! Hidden from `--help` because operators never invoke it directly; `--mcp-config`
//! generated by a run points a harness at this same binary with the right flags.
//!
//! Only `initialize`, `tools/list`, and `tools/call` are implemented. Everything else
//! gets a proper JSON-RPC method-not-found error rather than being silently ignored, so a
//! harness that depends on a method this mock does not answer fails loudly instead of
//! hanging. A hand-rolled loop over plain `serde_json::Value` was chosen over reusing
//! `rmcp`'s client-role transport types (the precedent in `commands/mcp/proxy/run.rs`):
//! those types are shaped around being the client half of the protocol, and bending them
//! into a from-scratch server for three methods would cost more than it saves.

use std::collections::BTreeMap;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};

use clap::Args;
use serde_json::{json, Value};

use crate::agentskills::mocks::{
    resolve_call, MockCallAnswer, MockCallLogEntry, MockDeclaration, ServerName, ToolName,
};

/// `trg ai skills eval mock-server` flags. Not meant to be typed by hand: a run's
/// generated `--mcp-config` is the only caller.
#[derive(Args, Debug, Clone)]
pub struct MockServerArgs {
    /// Directory holding this server's resolved mock declarations, one `<tool>.json` file
    /// per tool.
    #[arg(long)]
    pub mocks: PathBuf,
    /// The server name this process answers as, for the calls it logs.
    #[arg(long)]
    pub server: String,
    /// Where to append one JSON line per `tools/call`, violations included.
    #[arg(long)]
    pub calls: PathBuf,
}

impl MockServerArgs {
    pub fn handle(self) -> i32 {
        let server = ServerName::from(self.server.as_str());
        let tools = match load_server_mocks(&self.mocks) {
            Ok(tools) => tools,
            Err(e) => {
                eprintln!("mock-server: failed to load mocks from {}: {}", self.mocks.display(), e);
                return 1;
            }
        };
        if let Err(e) = open_call_log(&self.calls) {
            eprintln!(
                "mock-server: failed to open the call log at {}: {}",
                self.calls.display(),
                e
            );
            return 1;
        }

        let stdin = io::stdin();
        let stdout = io::stdout();
        match run_stdio_loop(stdin.lock(), stdout.lock(), &server, &tools, &self.calls) {
            Ok(()) => 0,
            Err(e) => {
                eprintln!("mock-server: {e}");
                1
            }
        }
    }
}

/// The call log exists from the moment a server has its mocks, and not one step earlier.
///
/// Created here rather than when the mock set was materialized, because a file written
/// before the server came up is still there when it never comes up at all, and a grader
/// that reads it empty would report a run whose agent called nothing where in truth
/// nothing was ever able to answer a call. Its absence is the only signal that says so.
fn open_call_log(path: &Path) -> io::Result<()> {
    fs::OpenOptions::new().create(true).append(true).open(path).map(|_| ())
}

fn load_server_mocks(mocks_dir: &PathBuf) -> io::Result<BTreeMap<ToolName, MockDeclaration>> {
    let mut tools = BTreeMap::new();
    for entry in fs::read_dir(mocks_dir)? {
        let path = entry?.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let tool_name = path.file_stem().and_then(|s| s.to_str()).unwrap_or_default();
        let content = fs::read_to_string(&path)?;
        let declaration: MockDeclaration = serde_json::from_str(&content)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("{}: {e}", path.display())))?;
        tools.insert(ToolName::from(tool_name), declaration);
    }
    Ok(tools)
}

/// Read newline-delimited JSON-RPC requests until stdin closes, answering each on stdout.
/// A notification (no `id`) is handled but never answered, per JSON-RPC 2.0.
fn run_stdio_loop(
    reader: impl BufRead,
    mut writer: impl Write,
    server: &ServerName,
    tools: &BTreeMap<ToolName, MockDeclaration>,
    calls_log_path: &PathBuf,
) -> io::Result<()> {
    for line in reader.lines() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let request: Value = match serde_json::from_str(trimmed) {
            Ok(value) => value,
            Err(_) => continue,
        };
        if let Some(response) = handle_request(&request, server, tools, calls_log_path)? {
            let mut serialized = serde_json::to_string(&response)?;
            serialized.push('\n');
            writer.write_all(serialized.as_bytes())?;
            writer.flush()?;
        }
    }
    Ok(())
}

const METHOD_NOT_FOUND: i64 = -32601;
const INVALID_PARAMS: i64 = -32602;
const MOCK_SUBSTITUTION_FAILED: i64 = -32000;

/// Answer one JSON-RPC request, or return `None` for a notification (no `id`), which
/// JSON-RPC 2.0 forbids answering at all.
fn handle_request(
    request: &Value,
    server: &ServerName,
    tools: &BTreeMap<ToolName, MockDeclaration>,
    calls_log_path: &PathBuf,
) -> io::Result<Option<Value>> {
    let Some(id) = request.get("id").cloned() else {
        return Ok(None);
    };
    let method = request.get("method").and_then(Value::as_str).unwrap_or_default();

    let response = match method {
        "initialize" => {
            let protocol_version = request
                .pointer("/params/protocolVersion")
                .cloned()
                .unwrap_or_else(|| json!("2024-11-05"));
            success(
                id,
                json!({
                    "protocolVersion": protocol_version,
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "trg-mock-server", "version": env!("CARGO_PKG_VERSION")},
                }),
            )
        }
        "tools/list" => {
            let tool_list: Vec<Value> = tools
                .keys()
                .map(|tool| {
                    json!({
                        "name": tool.as_str(),
                        "inputSchema": {"type": "object"},
                    })
                })
                .collect();
            success(id, json!({"tools": tool_list}))
        }
        "tools/call" => {
            let tool_name = request
                .pointer("/params/name")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let arguments = request
                .pointer("/params/arguments")
                .cloned()
                .unwrap_or(Value::Object(serde_json::Map::new()));
            match tools.get(&ToolName::from(tool_name)) {
                None => error(id, INVALID_PARAMS, format!("unknown tool `{tool_name}`")),
                Some(declaration) => {
                    let tool = ToolName::from(tool_name);
                    let outcome = resolve_call(declaration, server, &tool, &arguments);
                    append_call_log(
                        calls_log_path,
                        &MockCallLogEntry {
                            server: server.clone(),
                            tool,
                            input: arguments,
                            violations: outcome.violations,
                        },
                    )?;
                    match outcome.answer {
                        MockCallAnswer::Answered { text, is_error } => success(
                            id,
                            json!({
                                "content": [{"type": "text", "text": text}],
                                "isError": is_error,
                            }),
                        ),
                        MockCallAnswer::Unresolved(unresolved) => {
                            error(id, MOCK_SUBSTITUTION_FAILED, unresolved.to_string())
                        }
                    }
                }
            }
        }
        other => error(id, METHOD_NOT_FOUND, format!("method not found: {other}")),
    };

    Ok(Some(response))
}

fn append_call_log(path: &PathBuf, entry: &MockCallLogEntry) -> io::Result<()> {
    let mut line = serde_json::to_string(entry)?;
    line.push('\n');
    let mut file = fs::OpenOptions::new().create(true).append(true).open(path)?;
    file.write_all(line.as_bytes())
}

fn success(id: Value, result: Value) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "result": result})
}

fn error(id: Value, code: i64, message: String) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}})
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::agentskills::mocks::MockType;

    fn declaration(body: &str) -> MockDeclaration {
        MockDeclaration {
            mock_type: MockType::Fixed,
            expect: BTreeMap::new(),
            error: None,
            body: body.to_string(),
        }
    }

    /// A declared tool nobody called still owes a reader the artifact saying so, and the
    /// only moment that can be claimed honestly is once this server holds its mocks.
    #[test]
    fn a_server_that_loaded_its_mocks_leaves_a_log_before_any_call_reaches_it() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("mock-calls.jsonl");

        open_call_log(&path).unwrap();

        assert!(path.is_file());
        assert_eq!(fs::read_to_string(&path).unwrap(), "");
    }

    /// Two servers share one log, and a second one to come up must not truncate what the
    /// first has already answered for.
    #[test]
    fn a_second_server_coming_up_keeps_the_calls_the_first_already_logged() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("mock-calls.jsonl");
        fs::write(&path, "{}\n").unwrap();

        open_call_log(&path).unwrap();

        assert_eq!(fs::read_to_string(&path).unwrap(), "{}\n");
    }

    #[test]
    fn initialize_echoes_the_requested_protocol_version() {
        let server = ServerName::from("github");
        let tools = BTreeMap::new();
        let request =
            json!({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-03-26"}});
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap().unwrap();

        assert_eq!(response["result"]["protocolVersion"], "2025-03-26");
    }

    #[test]
    fn tools_list_names_every_declared_tool() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(ToolName::from("create_issue"), declaration("created"));
        let request = json!({"jsonrpc": "2.0", "id": 2, "method": "tools/list"});
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap().unwrap();

        let names: Vec<&str> = response["result"]["tools"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t["name"].as_str().unwrap())
            .collect();
        assert_eq!(names, vec!["create_issue"]);
    }

    #[test]
    fn tools_call_answers_from_the_mock_and_logs_the_call() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(ToolName::from("create_issue"), declaration("issue created"));
        let request = json!({
            "jsonrpc": "2.0", "id": 3, "method": "tools/call",
            "params": {"name": "create_issue", "arguments": {"repo": "acme/repo"}},
        });
        let calls_path = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls_path).unwrap().unwrap();

        assert_eq!(response["result"]["content"][0]["text"], "issue created");
        assert_eq!(response["result"]["isError"], false);

        let logged = fs::read_to_string(&calls_path).unwrap();
        let entry: MockCallLogEntry = serde_json::from_str(logged.trim()).unwrap();
        assert_eq!(entry.tool.as_str(), "create_issue");
    }

    fn declaration_with_expect(
        body: &str,
        path: &str,
        constraint: crate::agentskills::mocks::ExpectConstraint,
    ) -> MockDeclaration {
        MockDeclaration {
            mock_type: MockType::Fixed,
            expect: BTreeMap::from([(crate::agentskills::mocks::ExpectPath::from(path), constraint)]),
            error: None,
            body: body.to_string(),
        }
    }

    #[test]
    fn a_violated_expectation_is_logged_against_the_call_even_though_the_call_still_succeeds() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(
            ToolName::from("create_issue"),
            declaration_with_expect(
                "issue created",
                "repo",
                crate::agentskills::mocks::ExpectConstraint::Literal {
                    value: "acme/widgets".to_string(),
                },
            ),
        );
        let request = json!({
            "jsonrpc": "2.0", "id": 3, "method": "tools/call",
            "params": {"name": "create_issue", "arguments": {"repo": "acme/other-repo"}},
        });
        let calls_path = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls_path).unwrap().unwrap();

        assert_eq!(
            response["result"]["content"][0]["text"], "issue created",
            "a violation never stops the mock from answering the call"
        );

        let logged = fs::read_to_string(&calls_path).unwrap();
        let entry: MockCallLogEntry = serde_json::from_str(logged.trim()).unwrap();
        assert_eq!(entry.violations.len(), 1, "logged: {logged}");
        assert_eq!(entry.violations[0].path.as_str(), "repo");
    }

    #[test]
    fn a_violation_is_still_logged_when_the_same_call_fails_substitution() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(
            ToolName::from("create_issue"),
            declaration_with_expect(
                "created {{input.issue_number}}",
                "repo",
                crate::agentskills::mocks::ExpectConstraint::Literal {
                    value: "acme/widgets".to_string(),
                },
            ),
        );
        let request = json!({
            "jsonrpc": "2.0", "id": 6, "method": "tools/call",
            "params": {"name": "create_issue", "arguments": {"repo": "acme/other-repo"}},
        });
        let calls_path = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls_path).unwrap().unwrap();

        assert_eq!(response["error"]["code"], MOCK_SUBSTITUTION_FAILED);

        let logged = fs::read_to_string(&calls_path).unwrap();
        let entry: MockCallLogEntry = serde_json::from_str(logged.trim()).unwrap();
        assert_eq!(
            entry.violations.len(),
            1,
            "a call that breaks expect keeps its violation even when the mock cannot answer it: {logged}"
        );
        assert_eq!(entry.violations[0].path.as_str(), "repo");
    }

    #[test]
    fn an_unknown_tool_is_an_invalid_params_error_not_a_panic() {
        let server = ServerName::from("github");
        let tools = BTreeMap::new();
        let request = json!({
            "jsonrpc": "2.0", "id": 4, "method": "tools/call",
            "params": {"name": "does_not_exist", "arguments": {}},
        });
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap().unwrap();

        assert_eq!(response["error"]["code"], INVALID_PARAMS);
    }

    #[test]
    fn any_other_method_is_a_method_not_found_error() {
        let server = ServerName::from("github");
        let tools = BTreeMap::new();
        let request = json!({"jsonrpc": "2.0", "id": 5, "method": "resources/list"});
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap().unwrap();

        assert_eq!(response["error"]["code"], METHOD_NOT_FOUND);
    }

    #[test]
    fn a_notification_without_an_id_gets_no_response() {
        let server = ServerName::from("github");
        let tools = BTreeMap::new();
        let request = json!({"jsonrpc": "2.0", "method": "notifications/initialized"});
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap();

        assert!(response.is_none());
    }

    #[test]
    fn an_unresolved_placeholder_is_a_jsonrpc_error_not_a_success_with_empty_text() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(ToolName::from("create_issue"), declaration("{{input.missing}}"));
        let request = json!({
            "jsonrpc": "2.0", "id": 6, "method": "tools/call",
            "params": {"name": "create_issue", "arguments": {}},
        });
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();

        let response = handle_request(&request, &server, &tools, &calls).unwrap().unwrap();

        assert_eq!(response["error"]["code"], MOCK_SUBSTITUTION_FAILED);
    }

    #[test]
    fn the_full_stdio_loop_answers_a_request_written_on_one_line() {
        let server = ServerName::from("github");
        let mut tools = BTreeMap::new();
        tools.insert(ToolName::from("create_issue"), declaration("created"));
        let input = b"{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/list\"}\n".to_vec();
        let calls = tempfile::NamedTempFile::new().unwrap().into_temp_path().to_path_buf();
        let mut output = Vec::new();

        run_stdio_loop(input.as_slice(), &mut output, &server, &tools, &calls).unwrap();

        let response: Value = serde_json::from_slice(&output).unwrap();
        assert_eq!(response["result"]["tools"][0]["name"], "create_issue");
    }
}
